<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Câu hỏi · Mini Game</title><link rel="stylesheet" href="<?= base_url('assets/css/mini-game.css') ?>"></head><body><main class="game-shell"><header class="topbar"><div class="brand">Kho câu hỏi</div><nav class="nav"><a href="<?= site_url('mini-game/admin') ?>">← Bảng MC</a><a href="<?= site_url('mini-game/questions/export') ?>">Export CSV</a></nav></header><section class="card"><h2>Thêm / cập nhật câu hỏi</h2><?php if (session('error')): ?><p class="answer" style="background:#fee2e2"><?= esc(session('error')) ?></p><?php endif ?><form method="post" action="<?= site_url('mini-game/questions') ?>"><?= csrf_field() ?><input type="hidden" name="id" id="q-id"><div class="grid"><div><label class="field">Biển số<input name="plate_code" id="q-plate" required placeholder="75"></label><label class="field">Tỉnh/Thành<input name="province" id="q-province" required placeholder="Huế"></label><label class="field">3 địa điểm (mỗi dòng một mục)<textarea name="places" id="q-places"></textarea></label></div><div><label class="field">Đặc sản<input name="specialty" id="q-specialty"></label><label class="field">Sân bay<input name="airport" id="q-airport"></label><label class="field">UNESCO<input name="unesco" id="q-unesco"></label><label class="field">Thứ tự<input type="number" name="sort_order" id="q-order" value="0"></label><label><input type="checkbox" name="is_active" id="q-active" value="1" checked> Đang sử dụng</label></div></div><button class="btn primary">Lưu câu hỏi</button></form></section><section class="card" style="margin-top:18px;overflow:auto"><table class="question-table"><thead><tr><th>#</th><th>Biển số</th><th>Tỉnh/Thành</th><th>Câu phụ</th><th></th></tr></thead><tbody><?php foreach ($questions as $q): ?><tr><td><?= esc($q['sort_order']) ?></td><td><b><?= esc($q['plate_code']) ?></b></td><td><?= esc($q['province']) ?></td><td><?= array_sum([!empty($q['places']),!empty($q['specialty']),!empty($q['airport']),!empty($q['unesco'])]) ?> loại</td><td><button type="button" class="btn edit-q" data-q='<?= esc(json_encode($q, JSON_UNESCAPED_UNICODE), 'attr') ?>'>Sửa</button><form method="post" action="<?= site_url('mini-game/questions/'.$q['id'].'/delete') ?>" style="display:inline" onsubmit="return confirm('Xóa câu hỏi này?')"><?= csrf_field() ?><button class="btn bad">Xóa</button></form></td></tr><?php endforeach ?></tbody></table></section></main><script>document.querySelectorAll('.edit-q').forEach(b=>b.onclick=()=>{const q=JSON.parse(b.dataset.q);['id','plate','province','places','specialty','airport','unesco','order'].forEach(k=>document.querySelector('#q-'+k).value=q[k==='plate'?'plate_code':k==='order'?'sort_order':k]||'');document.querySelector('#q-active').checked=Number(q.is_active)===1;scrollTo({top:0,behavior:'smooth'})});</script></body></html>
